INSERT INTO demo_all_rows VALUES
    ('김정옥 영남요 분청사기 다기세트', 1, 3, '백토를 귀얄로 바르거나 담가 투박하고 자연스러운 결을 살린 분청 찻잔입니다.', '유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다.', '중성세제로 부드럽게 씻어 주세요.', '찻잔', '도자기', '다기·찻잔', '맑은 유약층과 은은한 비색', '@R@docs/demo-products/photoreal/staging/f01_A.webp', '@R@docs/demo-products/photoreal/staging/f01_B.webp', '@R@docs/demo-products/photoreal/staging/f01_C.webp'),
    ('신정희요 수제 이도다완', 1, 1, '손으로 빚은 형태 위에 유약을 얇게 입혀 구운 도자 찻잔입니다.', '차 한 잔을 따르면 손안에 따뜻함이 고스란히 전해집니다.', '유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다.', '찻잔', '도자기', '다기·찻잔', '맑은 유약층과 은은한 비색', '@R@docs/demo-products/photoreal/staging/d002_A.webp', NULL, NULL),
    ('광주요 백자 청화 다기 세트', 1, 1, '고운 백토를 물레에 올려 빚고 맑은 유약을 입혀 구운 찻잔입니다.', '흡수가 적어 냄새가 배지 않고 씻기 편합니다.', '흡수가 적어 냄새가 배지 않고 씻기 편합니다.', '찻잔', '백자', '다기·찻잔', '매끈한 유약과 깨끗한 흰 바탕', '@R@docs/demo-products/photoreal/staging/d003_A.webp', NULL, NULL),
    ('강진 청자 운학문 다기 세트', 1, 1, '은은한 비색 유약을 입혀 장작가마에서 구워 낸 청자 찻잔입니다.', '구름과 학이 어우러진 상서로운 문양입니다.', '유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다.', '찻잔', '청자', '다기·찻잔', '맑은 유약층과 은은한 비색', '@R@docs/demo-products/photoreal/staging/d004_A.webp', NULL, NULL),
    ('이종덕 옻칠 목다완 찻잔', 1, 1, '나무 바탕에 천연 옻칠을 겹겹이 입혀 마무리한 찻잔입니다.', '쓸수록 옻 특유의 깊은 윤기가 더해집니다.', '직사광선과 습기를 피하고 부드러운 천으로 닦아 주세요.', '찻잔', '원목 옻칠', '다기·찻잔', '겹겹이 입힌 옻칠의 깊은 윤기', '@R@docs/demo-products/photoreal/staging/d005_A.webp', NULL, NULL),
    ('영남요 백자 다기 찻잔', 1, 1, '고운 백토를 물레에 올려 빚고 맑은 유약을 입혀 구운 찻잔입니다.', '차 한 잔을 따르면 손안에 따뜻함이 고스란히 전해집니다.', '마른 천으로 닦아 두면 맑은 흰빛이 오래갑니다.', '찻잔', '백자', '다기·찻잔', '매끈한 유약과 깨끗한 흰 바탕', '@R@docs/demo-products/photoreal/staging/d006_A.webp', NULL, NULL),
    ('다도원 청자 상감 다관 및 잔세트', 1, 1, '은은한 비색 유약을 입혀 장작가마에서 구워 낸 청자 찻잔입니다.', '급격한 온도 변화만 피하면 오래 쓸 수 있습니다.', '유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다. 중성세제로 부드럽게 씻어 주세요.', '찻잔', '청자', '다기·찻잔', '맑은 유약층과 은은한 비색', '@R@docs/demo-products/photoreal/staging/d007_A.webp', NULL, NULL),
    ('광주요 소리잔 찻잔 세트', 1, 1, '손으로 빚은 형태 위에 유약을 얇게 입혀 구운 도자 찻잔입니다.', '차 한 잔을 따르면 손안에 따뜻함이 고스란히 전해집니다.', '급격한 온도 변화만 피하면 오래 쓸 수 있습니다.', '찻잔', '도자기', '다기·찻잔', '맑은 유약층과 은은한 비색', '@R@docs/demo-products/photoreal/staging/d008_A.webp', NULL, NULL),
    ('신정희요 분청 찻잔 세트', 1, 1, '백토를 귀얄로 바르거나 담가 투박하고 자연스러운 결을 살린 분청 찻잔입니다.', '급격한 온도 변화만 피하면 오래 쓸 수 있습니다.', '유약 속 잔 균열은 쓸수록 자연스럽게 깊어집니다. 중성세제로 부드럽게 씻어 주세요.', '찻잔', '도자기', '다기·찻잔', '맑은 유약층과 은은한 비색', '@R@docs/demo-products/photoreal/staging/d009_A.webp', NULL, NULL),
